16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Locale;
22	
23	import org.springframework.samples.petclinic.model.Owner;
24	
25	/**
26	 * The owner identity key: the SHA-256 hex of
27	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Duplicate detection
28	 * compares this key; the soft-match compares {@link #soundex(String)} of the last name.
29	 */
30	public final class IdentityKeys {
31	
32	    private IdentityKeys() {
33	    }
34	
35	    /** The identity key of the given owner. */
36	    public static String of(Owner owner) {
37	        String raw = orEmpty(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + soundex(owner.getLastName());
38	        return sha256Hex(raw);
39	    }
40	
41	    /** The American Soundex code of {@code name} (letter + 3 digits), or empty when there is no letter. */
42	    public static String soundex(String name) {
43	        String letters = (name == null ? "" : name.toUpperCase(Locale.ROOT)).replaceAll("[^A-Z]", "");
44	        if (letters.isEmpty()) {
45	            return "";
46	        }
47	        StringBuilder out = new StringBuilder().append(letters.charAt(0));
48	        char prev = code(letters.charAt(0));
49	        for (int i = 1; i < letters.length() && out.length() < 4; i++) {
50	            char c = letters.charAt(i);
51	            char digit = code(c);
52	            if (digit != '0' && digit != prev) {
53	                out.append(digit);
54	            }
55	            if (c != 'H' && c != 'W') {
56	                prev = digit;
57	            }
58	        }
59	        while (out.length() < 4) {
60	            out.append('0');
61	        }
62	        return out.toString();
63	    }
64	
65	    private static char code(char c) {
66	        return switch (c) {
67	            case 'B', 'F', 'P', 'V' -> '1';
68	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
69	            case 'D', 'T' -> '3';
70	            case 'L' -> '4';
71	            case 'M', 'N' -> '5';
72	            case 'R' -> '6';
73	            default -> '0';
74	        };
75	    }
76	
77	    private static String orEmpty(String value) {
78	        return value == null ? "" : value;
79	    }
80	
81	    private static String sha256Hex(String value) {
82	        try {
83	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
84	            StringBuilder hex = new StringBuilder(digest.length * 2);
85	            for (byte b : digest) {
86	                hex.append(String.format("%02x", b));
87	            }
88	            return hex.toString();
89	        }
90	        catch (NoSuchAlgorithmException ex) {
91	            throw new IllegalStateException(ex);
92	        }
93	    }
94	}
