16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.util.Collection;
23	import java.util.HashSet;
24	import java.util.Set;
25	
26	import org.springframework.samples.petclinic.model.Owner;
27	
28	/**
29	 * Builds and reads the unified {@code <REGION><FY><HASH8><CHK>} owner member id: REGION is the
30	 * region resolved from the postcode, FY is the 2-digit fiscal year of the registration date, HASH8
31	 * is the first 8 upper-case hex characters of SHA-256 over (normalizedTelephone + lastName), and CHK
32	 * is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}.
33	 */
34	public final class MemberIds {
35	
36	    private MemberIds() {
37	    }
38	
39	    /** Build the {@code <REGION><FY><HASH8><CHK>} member id from region, registration fiscal year and the telephone+lastName hash. */
40	    public static String build(String city, String postcode, String telephone, String lastName, LocalDate registrationDate) {
41	        String body = Localities.regionFor(city, postcode)
42	            + String.format("%02d", FiscalYears.startYear(registrationDate) % 100)
43	            + hash8(telephone + lastName);
44	        return body + CheckDigits.luhn(body);
45	    }
46	
47	    /**
48	     * Build the member id, then de-duplicate it against {@code existingOwners} by appending
49	     * {@code -<n>} with the smallest {@code n >= 2} that makes it unique.
50	     */
51	    public static String buildUnique(String city, String postcode, String telephone, String lastName,
52	            LocalDate registrationDate, Collection<Owner> existingOwners) {
53	        String base = build(city, postcode, telephone, lastName, registrationDate);
54	        Set<String> taken = new HashSet<>();
55	        for (Owner owner : existingOwners) {
56	            taken.add(owner.getMemberId());
57	        }
58	        String candidate = base;
59	        for (int n = 2; taken.contains(candidate); n++) {
60	            candidate = base + "-" + n;
61	        }
62	        return candidate;
63	    }
64	
65	    /** The region portion of a member id (its leading run of letters), or null when absent. */
66	    public static String regionOf(String memberId) {
67	        if (memberId == null) {
68	            return null;
69	        }
70	        int end = 0;
71	        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
72	            end++;
73	        }
74	        return memberId.substring(0, end);
75	    }
76	
77	    /** The {@code FY<YY>} label carried by the member id (its 2 fiscal-year digits after the region), or null when absent. */
78	    public static String fiscalYearLabel(String memberId) {
79	        String region = regionOf(memberId);
80	        return region == null ? null : "FY" + memberId.substring(region.length(), region.length() + 2);
81	    }
82	
83	    private static String hash8(String value) {
84	        try {
85	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
86	            return String.format("%02X%02X%02X%02X", digest[0], digest[1], digest[2], digest[3]);
87	        }
88	        catch (NoSuchAlgorithmException ex) {
89	            throw new IllegalStateException(ex);
90	        }
91	    }
92	}
