16	package org.springframework.samples.petclinic.util;
17	
18	/**
19	 * Resolves an owner's '&lt;TIER&gt;_&lt;AREA&gt;' segment from their membership level and region.
20	 *
21	 * <p>TIER is {@code PREMIUM} at membership level 3 or above, otherwise {@code STANDARD}. AREA is
22	 * {@code METRO} for a known region (NSW/VIC/QLD), otherwise {@code REGIONAL}.
23	 */
24	public final class OwnerSegments {
25	
26	    private OwnerSegments() {
27	    }
28	
29	    /** Compose the segment from the resolved {@code membershipLevel} and {@code region}. */
30	    public static String of(int membershipLevel, String region) {
31	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
32	        String area = Localities.timezoneFor(region) != null ? "METRO" : "REGIONAL";
33	        return tier + "_" + area;
34	    }
35	}
