1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
13	
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName",
24	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
27	    @Mapping(target = "memberId", expression = "java(owner.getMemberId())")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
31	    @Mapping(target = "locality",
32	        expression = "java(org.springframework.samples.petclinic.util.MemberIds.regionOf(owner.getMemberId()))")
33	    @Mapping(target = "ownerSegment",
34	        expression = "java(org.springframework.samples.petclinic.util.OwnerSegments.of(membershipLevel(owner), org.springframework.samples.petclinic.util.MemberIds.regionOf(owner.getMemberId())))")
35	    @Mapping(target = "timezone",
36	        expression = "java(org.springframework.samples.petclinic.util.Localities.timezoneFor(org.springframework.samples.petclinic.util.MemberIds.regionOf(owner.getMemberId())))")
37	    @Mapping(target = "contactPreference",
38	        expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
39	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
40	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
41	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
42	    @Mapping(target = "telephoneDisplay",
43	        expression = "java(org.springframework.samples.petclinic.util.TelephoneFormatter.toDisplay(owner.getTelephone()))")
44	    @Mapping(target = "selfLink",
45	        expression = "java(owner.getId() == null ? null : \"/api/owners/\" + owner.getId())")
46	    OwnerDto toOwnerDto(Owner owner);
47	
48	    /** Age band derived from birthDate against registrationDate: MINOR (under 18), ADULT (18-64) or SENIOR (65+); null when birthDate is absent. */
49	    default String ageBand(Owner owner) {
50	        java.time.LocalDate birthDate = owner.getBirthDate();
51	        if (birthDate == null || owner.getRegistrationDate() == null) {
52	            return null;
53	        }
54	        int age = java.time.Period.between(birthDate, owner.getRegistrationDate()).getYears();
55	        if (age < 18) {
56	            return "MINOR";
57	        }
58	        return age < 65 ? "ADULT" : "SENIOR";
59	    }
60	
61	    /** The single duplicate-detection key: SHA-256 hex of normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName). */
62	    default String identityKey(Owner owner) {
63	        return org.springframework.samples.petclinic.util.IdentityKeys.of(owner);
64	    }
65	
66	    default String orEmpty(String value) {
67	        return value == null ? "" : value;
68	    }
69	
70	    /** Membership points: +2 for an email, +1 when namesakeCount is 0, +2 for a household of 3 or more, +3 for tenure over 365 days. */
71	    default int membershipPoints(Owner owner) {
72	        return org.springframework.samples.petclinic.util.MembershipLevels.points(owner);
73	    }
74	
75	    /** The owner's stored household-capped level when frozen at create, otherwise the level derived from points. */
76	    default Integer membershipLevel(Owner owner) {
77	        Integer stored = owner.getMembershipLevel();
78	        return stored != null ? stored : org.springframework.samples.petclinic.util.MembershipLevels.level(owner);
79	    }
80	
81	    /** The 'FY<YY>' fiscal year carried by the memberId; null when the memberId is absent. */
82	    default String fiscalYear(Owner owner) {
83	        return org.springframework.samples.petclinic.util.MemberIds.fiscalYearLabel(owner.getMemberId());
84	    }
85	
86	    Owner toOwner(OwnerDto ownerDto);
87	
88	    @Mapping(target = "id", ignore = true)
89	    @Mapping(target = "pets", ignore = true)
90	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
91	    @Mapping(target = "registrationDate", expression = "java(effectiveRegistrationDate(ownerDto))")
92	    @Mapping(target = "address", expression = "java(org.springframework.samples.petclinic.util.AddressNormalizer.compose(ownerDto.getAddressLine1(), ownerDto.getAddressLine2(), ownerDto.getAddress()))")
93	    Owner toOwner(OwnerFieldsDto ownerDto);
94	
95	    /** The supplied registration date, or today's date when absent, rolled forward off weekends to a business day. */
96	    default java.time.LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerDto) {
97	        java.time.LocalDate supplied = ownerDto.getRegistrationDate();
98	        return org.springframework.samples.petclinic.util.BusinessDays.toBusinessDay(
99	            supplied != null ? supplied : java.time.LocalDate.now());
100	    }
101	
102	    /** Normalize to E.164 so the create path stores, and duplicate detection compares, that form. */
103	    @Named("normalizeTelephone")
104	    default String normalizeTelephone(String telephone) {
105	        return TelephoneNormalizer.toE164(telephone);
106	    }
107	
108	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
109	
110	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
111	
112	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
113	        OwnerPageDto ownerPageDto = new OwnerPageDto();
114	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
115	        ownerPageDto.setPage(ownerPage.getNumber());
116	        ownerPageDto.setSize(ownerPage.getSize());
117	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
118	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
119	        return ownerPageDto;
120	    }
121	}
