17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.concurrent.atomic.AtomicInteger;
20	
21	/**
22	 * Immutable structured audit event emitted when an owner is created. It carries
23	 * the owner's current primary identifier: the {@code customerCode} today, and
24	 * whatever replaces it later (e.g. a unified {@code memberId}), passed in by the
25	 * caller so this event stays agnostic to which identifier is primary.
26	 */
27	public record OwnerCreatedEvent(int seq, Integer ownerId, String customerCode, Integer membershipLevel) {
28	
29	    private static final AtomicInteger SEQ = new AtomicInteger();
30	
31	    /** Next event for an owner, stamped with a monotonically increasing {@code seq} across creates. */
32	    public static OwnerCreatedEvent next(Integer ownerId, String primaryIdentifier, Integer membershipLevel) {
33	        return new OwnerCreatedEvent(SEQ.incrementAndGet(), ownerId, primaryIdentifier, membershipLevel);
34	    }
35	
36	    /** Compact JSON rendering with a stable field order. */
37	    public String toJson() {
38	        return String.format(
39	            "{\"seq\":%d,\"ownerId\":%s,\"customerCode\":%s,\"membershipLevel\":%s,\"event\":\"OWNER_CREATED\"}",
40	            seq, ownerId, quote(customerCode), membershipLevel);
41	    }
42	
43	    private static String quote(String value) {
44	        return value == null ? "null" : "\"" + value + "\"";
45	    }
46	}
